CREATE OR ALTER PROCEDURE [dbo].[uspQcInspectionLine_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @QCInspectionId UNIQUEIDENTIFIER = NULL
	, @IngredientId UNIQUEIDENTIFIER = NULL
	, @GoodsReceiptLineId UNIQUEIDENTIFIER = NULL
	, @Criterion NVARCHAR(MAX) = NULL
	, @Result NVARCHAR(MAX) = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[QCInspectionId]
			, t.[IngredientId]
			, t.[Temperature]
			, t.[Weight]
			, t.[Appearance]
			, t.[Packaging]
			, t.[ExpiryDate]
			, t.[Result]
			, t.[Remark]
			, t.[GoodsReceiptLineId]
			, t.[Criterion]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[QCInspectionLine] AS t
		
		WHERE 1 = 1
			AND (@QCInspectionId IS NULL OR t.[QCInspectionId] = @QCInspectionId)
			AND (@IngredientId IS NULL OR t.[IngredientId] = @IngredientId)
			AND (@GoodsReceiptLineId IS NULL OR t.[GoodsReceiptLineId] = @GoodsReceiptLineId)
			AND (ISNULL(@Criterion, '') = '' OR t.[Criterion] LIKE CONCAT('%', @Criterion, '%'))
			AND (ISNULL(@Result, '') = '' OR t.[Result] LIKE CONCAT('%', @Result, '%'))
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'qCInspectionId' THEN r.[QCInspectionId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'qCInspectionId' THEN r.[QCInspectionId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'ingredientId' THEN r.[IngredientId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'ingredientId' THEN r.[IngredientId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'temperature' THEN r.[Temperature] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'temperature' THEN r.[Temperature] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'weight' THEN r.[Weight] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'weight' THEN r.[Weight] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'appearance' THEN r.[Appearance] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'appearance' THEN r.[Appearance] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'packaging' THEN r.[Packaging] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'packaging' THEN r.[Packaging] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'expiryDate' THEN r.[ExpiryDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'expiryDate' THEN r.[ExpiryDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'result' THEN r.[Result] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'result' THEN r.[Result] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'remark' THEN r.[Remark] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'remark' THEN r.[Remark] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'goodsReceiptLineId' THEN r.[GoodsReceiptLineId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'goodsReceiptLineId' THEN r.[GoodsReceiptLineId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'criterion' THEN r.[Criterion] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'criterion' THEN r.[Criterion] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
